#include <vector>
#include <queue>
#include <algorithm>

class Solution {
public:
    int maximumInvitations(std::vector<int>& favorite) {
        int n = favorite.size();
        std::vector<int> inDegree(n, 0);
        for (int f : favorite) inDegree[f]++;

        std::queue<int> q;
        for (int i = 0; i < n; ++i) {
            if (inDegree[i] == 0) q.push(i);
        }

        std::vector<int> maxDepth(n, 1);
        while (!q.empty()) {
            int curr = q.front();
            q.pop();
            int nxt = favorite[curr];
            maxDepth[nxt] = std::max(maxDepth[nxt], maxDepth[curr] + 1);
            if (--inDegree[nxt] == 0) q.push(nxt);
        }

        int maxCycleGe3 = 0;
        int sum2Cycles = 0;
        std::vector<bool> visited(n, false);

        for (int i = 0; i < n; ++i) {
            if (inDegree[i] > 0 && !visited[i]) {
                int cycleLen = 0;
                int curr = i;
                while (!visited[curr]) {
                    visited[curr] = true;
                    curr = favorite[curr];
                    cycleLen++;
                }

                if (cycleLen == 2) {
                    int u = i;
                    int v = favorite[i];
                    sum2Cycles += maxDepth[u] + maxDepth[v];
                } else {
                    maxCycleGe3 = std::max(maxCycleGe3, cycleLen);
                }
            }
        }

        return std::max(maxCycleGe3, sum2Cycles);
    }
};

import java.util.*;

class Solution {
    public int maximumInvitations(int[] favorite) {
        int n = favorite.length;
        int[] inDegree = new int[n];
        for (int f : favorite) inDegree[f]++;

        Deque<Integer> q = new ArrayDeque<>();
        for (int i = 0; i < n; i++) {
            if (inDegree[i] == 0) q.offer(i);
        }

        int[] maxDepth = new int[n];
        Arrays.fill(maxDepth, 1);

        while (!q.isEmpty()) {
            int curr = q.poll();
            int nxt = favorite[curr];
            maxDepth[nxt] = Math.max(maxDepth[nxt], maxDepth[curr] + 1);
            if (--inDegree[nxt] == 0) q.offer(nxt);
        }

        int maxCycleGe3 = 0;
        int sum2Cycles = 0;
        boolean[] visited = new boolean[n];

        for (int i = 0; i < n; i++) {
            if (inDegree[i] > 0 && !visited[i]) {
                int cycleLen = 0;
                int curr = i;
                while (!visited[curr]) {
                    visited[curr] = true;
                    curr = favorite[curr];
                    cycleLen++;
                }

                if (cycleLen == 2) {
                    int u = i;
                    int v = favorite[i];
                    sum2Cycles += maxDepth[u] + maxDepth[v];
                } else {
                    maxCycleGe3 = Math.max(maxCycleGe3, cycleLen);
                }
            }
        }

        return Math.max(maxCycleGe3, sum2Cycles);
    }
}

